package com.robertx22.age_of_exile.airship.adventure;
import java.util.List;
/** First authored steps only, not a claim that all eight complete personal campaigns exist. */
public final class AdventureCatalog {
    private AdventureCatalog() {}
    public enum Metric { FISH, BIOME, SAPLING, DELIVERY }
    public record Quest(String id,String npc,String title,Metric metric,String item,int target,String objective,String request,String thanks) {}
    public static final List<Quest> QUESTS=List.of(
        new Quest("captain.quiet_water","captain","Тихая вода",Metric.FISH,"",3,"рыбы, пойманные после принятия",
            "Давно не рыбачил. Поймай три рыбы после нашего разговора, хорошо? Когда вернёшься, расскажешь, где клевало.",
            "Три штуки! А я однажды просидел с удочкой полдня и поймал только собственный сапог. Спасибо, что сходил. Расскажешь, как там у воды?"),
        new Quest("mara.unfinished_map","mara","Незаконченная карта",Metric.BIOME,"",3,"разных биома после принятия",
            "Мне нужны наблюдения из трёх разных биомов после нашего разговора. Записывай, что увидишь, даже если там окажется совсем не то, чего мы ожидали.",
            "Спасибо, отмечу все три места. Видишь старую поправку? Когда-то я её стёрла, потому что стеснялась ошибки. Теперь оставляю, чтобы самой не наступить на те же грабли."),
        new Quest("bram.shared_table","quartermaster","Не только припасы",Metric.DELIVERY,"minecraft:bread",8,"хлеба для общего стола",
            "Принеси восемь хлебов для общего стола. Сухие пайки всем уже надоели, да и соберёмся хоть раз вместе.",
            "Раньше я записывал только, сколько порций осталось. Сегодня запишу, кто пришёл к столу. Это разные списки. Спасибо."),
        new Quest("oren.new_roots","oren","Новые корни",Metric.SAPLING,"",4,"посаженных саженца после принятия",
            "Посадишь четыре саженца после нашего разговора? Выбери место, где им хватит пространства. Мне потом интересно будет посмотреть, как они растут.",
            "Ты оставил после себя то, что будет расти. Я всё думаю, что мои руки годятся только удерживать тяжёлое. Может, я просто давно не начинал с малого."),
        new Quest("veya.light_at_gangway","veya","Свет у трапа",Metric.DELIVERY,"minecraft:torch",4,"факела для возвращающихся",
            "Принеси четыре факела, поставлю их у трапа. А то вчера возвращалась в темноте и чуть не свалилась. Брам, конечно, всё видел.",
            "Однажды я ушла, не оставив огня. Думала, кому надо — найдут дорогу. Больше не хочу проверять, кто сумеет вернуться без помощи. Спасибо."),
        new Quest("selin.her_own_place","selin","Место для лекаря",Metric.DELIVERY,"minecraft:baked_potato",2,"печёных картофеля для Селин",
            "Принесёшь два печёных картофеля? Один для тебя, один для меня. Я тут увлеклась работой и опять пропустила ужин.",
            "Я всё собиралась сначала проверить остальных. Потом поняла: если ты ждёшь меня за столом, я не могу снова притвориться, что мне ничего не нужно. Посидишь со мной?"),
        new Quest("lysander.ordinary_names","lysander","Обычные имена",Metric.DELIVERY,"minecraft:paper",3,"листа бумаги для списка имён",
            "Мне нужны три листа бумаги. Хочу записать имена людей, которые нам помогали. Иначе однажды обнаружу, что помню только тех, о ком сочинил песни.",
            "Здесь нет рифмы. Есть имя кока, который раздал последний хлеб, и вахтенного, который не покинул пост. Раньше я сделал бы из них красивый припев. Сегодня оставлю людьми."),
        new Quest("tik.spare_key","tik","Не запасная дружба",Metric.DELIVERY,"minecraft:copper_ingot",1,"медный слиток для запасного ключа",
            "Принеси один медный слиток. Сделаю запасной ключ и отдам Орену. Нет, первый я не терял! Ладно, потерял. Пойдёшь со мной, когда буду ему говорить?",
            "Заготовка готова. Орену скажу сам, без сообщения через Мару. Если он рассердится, ты не обязан меня защищать. Но можешь остаться рядом. Так меньше хочется спрятаться в ящик.")
    );
    public static Quest find(String id){return QUESTS.stream().filter(q->q.id.equals(id)).findFirst().orElse(null);}
    public static Quest personal(String npc){return QUESTS.stream().filter(q->q.npc.equals(npc)).findFirst().orElse(null);}
}
